import { domainModelSpec } from './contract.ts'
import backendPrimitives from './backend.primitives.json'
import backendTree from './backend.tree.json'

export const ServiceState = S.Literals(['checking', 'reachable', 'unreachable'])
export type ServiceState = typeof ServiceState.Type

export const Model = S.Struct({
  apiUrl: S.String,
  state: ServiceState,
  checks: S.Number,
  detail: S.String,
})
export type Model = typeof Model.Type

export const Ticked = taggedStruct('Ticked')
export const SucceededReachService = taggedStruct('SucceededReachService', {
  status: S.Number,
})
export const FailedReachService = taggedStruct('FailedReachService', { error: S.String })

export const Message = S.Union([
  Ticked,
  SucceededReachService,
  FailedReachService,
])
export type Message = typeof Message.Type

export const ports = { inbound: {}, outbound: {} }

export const ReachBackendService = Command.define('ReachBackendService', {
  args: { apiUrl: S.String },
  messages: [SucceededReachService, FailedReachService],
  execute: ({ apiUrl }) =>
    Effect.tryPromise({
      try: async () => {
        const response = await fetch(
          `${apiUrl.replace(/\/$/u, '')}/rpc/`,
          {
            method: 'POST',
            credentials: 'include',
            headers: { 'content-type': 'application/ndjson' },
            body:
              JSON.stringify({
                _tag: 'Request',
                id: 1,
                tag: 'authoring.health',
                payload: {},
                traceId: '0123456789abcdef0123456789abcdef',
                spanId: '0123456789abcdef',
                sampled: true,
                headers: [],
              }) + '\n',
          },
        )
        const body = await response.text()
        if (!response.ok || !body.includes('"_tag":"Success"')) {
          throw new Error(
            `authoring.health failed (${response.status.toString()}): ${body}`,
          )
        }
        return response
      },
      catch: error => String(error),
    }).pipe(
      Effect.map(response => SucceededReachService({ status: response.status })),
      Effect.catch(error =>
        Effect.succeed(FailedReachService({ error: String(error) })),
      ),
    ),
})

export const Flags = S.Struct({ apiUrl: S.String })
export type Flags = typeof Flags.Type

export const init: Runtime.ElementInit<Model, Message, Flags> = flags => ({ model: { apiUrl: flags.apiUrl, state: 'checking', checks: 0, detail: 'Connecting' }, commands: [ReachBackendService({ apiUrl: flags.apiUrl })] })

type UpdateReturn = { readonly model: Model; readonly commands?: ReadonlyArray<Command.Command<Message>> }

export const update = (model: Model, message: Message): UpdateReturn =>
  M.value(message).pipe(
    M.withReturnType<UpdateReturn>(),
    M.tagsExhaustive({
      Ticked: () => ({ model: { ...model, state: 'checking' }, commands: [ReachBackendService({ apiUrl: model.apiUrl })] }),
      SucceededReachService: ({ status }) => ({ model: {
          ...model,
          state: 'reachable',
          checks: model.checks + 1,
          detail: `Service reachable · check ${model.checks + 1} · HTTP ${status}`,
        }, commands: [] }),
      FailedReachService: ({ error }) => ({ model: { ...model, state: 'unreachable', detail: error }, commands: [] }),
    }),
  )

const POLL_INTERVAL = Duration.seconds(2)

export const subscriptions = Subscription.make<Model, Message>()(_entry => ({
  poll: Subscription.persistent(
    Stream.tick(POLL_INTERVAL).pipe(Stream.map(Ticked)),
  ),
}))

const primitiveByRef = new Map(
  backendPrimitives.map(primitive => [primitive.ref, primitive]),
)

const primitiveView = (
  node: (typeof backendTree.nodes)[number],
  h: HtmlBuilder<Message>,
): Html => {
  const primitive = primitiveByRef.get(node.primitive)
  return h.li(
    [h.Class('rounded-md border border-border bg-surface-raised p-4')],
    [
      h.div([h.Class('text-label font-semibold text-fg-heading')], [
        primitive?.title ?? node.primitive,
      ]),
      h.p([h.Class('mt-1 text-body-s text-fg-muted')], [
        primitive?.summary ?? 'Catalog-defined backend primitive',
      ]),
    ],
  )
}

export const view = (model: Model, h: HtmlBuilder<Message>): Html =>
  h.div(
    [
      h.Class(
        'flex flex-col gap-4 rounded-lg border border-border bg-surface p-5 shadow-card',
      ),
      h.Attribute(
        'data-builder-render-state',
        model.state === 'checking'
          ? 'loading'
          : model.state === 'reachable'
            ? 'ready'
            : 'error',
      ),
    ],
    [
      h.div([h.Class('overline')], ['Backend']),
      h.div([h.Class('text-heading-m font-semibold text-fg-heading')], [
        domainModelSpec.entity.name,
      ]),
      h.p([h.Class('text-body-s text-fg-muted')], [
        `${domainModelSpec.fields.length} fields · ${domainModelSpec.operations.length} operations · catalog layout`,
      ]),
      h.ul([h.Class('grid gap-3')], [
        ...backendTree.nodes.map(node => primitiveView(node, h)),
      ]),
      h.div(
        [
          h.Class(
            model.state === 'unreachable'
              ? 'text-caption text-fg-error'
              : model.state === 'checking'
                ? 'text-caption text-fg-accent'
                : 'text-caption text-fg-success',
          ),
          h.Attribute('data-backend-service-state', model.state),
          h.Attribute('data-backend-service-checks', model.checks.toString()),
        ],
        [model.detail],
      ),
    ],
  )

export const makeElement = (container: HTMLElement, flags: Flags) =>
  Runtime.makeElement({
    Model,
    Flags,
    flags: Effect.succeed(flags),
    init,
    update,
    view,
    subscriptions,
    ports,
    container,
    devTools: { Message },
  })
